import * as React from "react"
import { Check } from "lucide-react"

import { Badge, BadgeDot } from "@/components/ui/badge"

/**
 * Agent status vocabulary. Grays for everything Fork handles on its own,
 * the orange tint only for things that are live, done, or waiting on the user.
 */
export type AgentStatus =
  | "running"
  | "scheduled"
  | "paused"
  | "needs-approval"
  | "live"
  | "done"
  | "active"
  | "failed"

const config: Record<
  AgentStatus,
  {
    label: string
    variant: "default" | "brand" | "destructive"
    tone?: "brand" | "ink" | "muted" | "destructive"
    check?: boolean
  }
> = {
  running: { label: "Running", variant: "default", tone: "ink" },
  scheduled: { label: "Scheduled", variant: "default", tone: "muted" },
  paused: { label: "Paused", variant: "default", tone: "muted" },
  "needs-approval": { label: "Needs approval", variant: "brand", tone: "brand" },
  live: { label: "Live", variant: "brand", tone: "brand" },
  active: { label: "Active", variant: "brand", tone: "brand" },
  done: { label: "Done", variant: "brand", check: true },
  failed: { label: "Failed", variant: "destructive", tone: "destructive" },
}

function StatusBadge({
  status,
  children,
  ...props
}: Omit<React.ComponentProps<typeof Badge>, "variant"> & {
  status: AgentStatus
}) {
  const c = config[status]
  return (
    <Badge variant={c.variant} {...props}>
      {c.check ? <Check /> : <BadgeDot tone={c.tone} />}
      {children ?? c.label}
    </Badge>
  )
}

export { StatusBadge }

import * as React from "react"
import { Check } from "lucide-react"

import { cn } from "@/lib/utils"

/**
 * TaskList / TaskRow — the agent's suggestions for a site.
 * Each row: a state marker, title + one-line meta, and ONE trailing action.
 * Markers: "pending" ink dot, "approval" orange dot, "done" orange check.
 */
type TaskState = "pending" | "approval" | "done"

function TaskList({ className, ...props }: React.ComponentProps<"ul">) {
  return (
    <ul
      data-slot="task-list"
      className={cn("flex flex-col divide-y divide-border-subtle", className)}
      {...props}
    />
  )
}

function TaskMarker({ state }: { state: TaskState }) {
  if (state === "done") {
    return (
      <span className="grid size-5 shrink-0 place-items-center rounded-full bg-brand text-brand-foreground">
        <Check className="size-3" strokeWidth={3} aria-hidden="true" />
      </span>
    )
  }
  return (
    <span className="grid size-5 shrink-0 place-items-center" aria-hidden="true">
      <span
        className={cn(
          "size-1.5 rounded-full",
          state === "approval" ? "bg-brand" : "bg-foreground"
        )}
      />
    </span>
  )
}

function TaskRow({
  state = "pending",
  title,
  meta,
  action,
  className,
  ...props
}: Omit<React.ComponentProps<"li">, "title"> & {
  state?: TaskState
  title: React.ReactNode
  meta?: React.ReactNode
  action?: React.ReactNode
}) {
  return (
    <li
      data-slot="task-row"
      data-state={state}
      className={cn("flex items-center gap-3 py-3 first:pt-0 last:pb-0", className)}
      {...props}
    >
      <TaskMarker state={state} />
